// Browser output is generated by TypeScript under dist/. No private Hasura
// credential is sent to the browser; the authenticated server supplies it.
const hasuraWindow = window as unknown as { __env: Record<string, unknown> };
hasuraWindow.__env.isAdminSecretSet = true;
hasuraWindow.__env.isAccessKeySet = true;
// Public transport marker for the vendor console, never an upstream credential.
// The proxy discards it and independently authenticates every session request.
hasuraWindow.__env.adminSecret = "fv-session-proxy";
hasuraWindow.__env.enableTelemetry = false;
const localFonts = document.createElement("style");
localFonts.textContent =
  "body, .font-sans { font-family: system-ui, sans-serif !important; } code, pre, .font-mono { font-family: ui-monospace, monospace !important; }";
document.head.append(localFonts);
const hasuraFetch = window.fetch.bind(window);
window.fetch = (input, init) => {
  const request = input instanceof Request ? input : undefined;
  const url = new URL(request?.url ?? String(input), window.location.href);
  if (
    url.origin !== window.location.origin ||
    !url.pathname.startsWith("/hasura/")
  )
    return hasuraFetch(input, init);
  const headers = new Headers(request?.headers);
  new Headers(init?.headers).forEach((value, key) => headers.set(key, value));
  const method = (init?.method ?? request?.method ?? "GET").toUpperCase();
  if (!["GET", "HEAD"].includes(method)) {
    const csrf =
      document.cookie
        .split("; ")
        .find((item) => item.startsWith("fv_csrf="))
        ?.slice("fv_csrf=".length) ?? "";
    headers.set("x-csrf-token", csrf);
  }
  return hasuraFetch(input, { ...init, headers, credentials: "same-origin" });
};
